function validate([root]) {
  const values = root.filter(v => v !== null);
  if (values.length < 1) return 'The tree needs at least 1 node.';
  if (values.length > 10000) return 'The tree has at most 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -100000 || v > 100000)) return 'Every node value is between -10^5 and 10^5.';
  return null;
}

