function maxLevelSum(root) {
  let bestLevel = 1;
  let bestSum = -Infinity;
  let level = 0;
  let queue = [root];

  while (queue.length > 0) {
    level++;
    let sum = 0;
    const next = [];
    for (const node of queue) {
      sum += node.val;
      if (node.left !== null) {
        next.push(node.left);
      }
      if (node.right !== null) {
        next.push(node.right);
      }
    }
    if (sum > bestSum) {
      bestSum = sum;
      bestLevel = level;
    }
    queue = next;
  }
  return bestLevel;
}

