function maxLevelSum(root) {
  // Depth-first: add every node's value into the slot for its depth, then scan the slots.
  const sums = [];
  const visit = (node, depth) => {
    if (!node) return;
    sums[depth] = (sums[depth] || 0) + node.val;
    visit(node.left, depth + 1);
    visit(node.right, depth + 1);
  };
  visit(root, 0);
  const top = Math.max(...sums);
  return sums.indexOf(top) + 1;
}

